            ],
            "should": [
                {
                    "multi_match": {
                        "query": adresse,
                        "fields": ['idTypeVoie^5', 'nomVoieNorm^15'],
                        "type": "most_fields",
                        "fuzziness": 1,
                        "minimum_should_match": 1
                    }
                },
                {
                    "multi_match": {
                        "query": adresse,
                        "fields": ['nomVoieNorm.ngrams^1'],
                        "type": "most_fields",
                        "minimum_should_match": 1
                    }
                }
            ],
            "minimum_should_match": 1
        }
    },
    "sort": [
        {"_score": {"order": "desc"}},
        {
            "_script": {
                "type": "number",
                "script": {
                    "source": "int length_nomVoie = (doc.containsKey('nomVoieNorm.keyword') && doc['nomVoieNorm.keyword'].size() &gt; 0) ? doc['nomVoieNorm.keyword'].value.length() : 0; int length_idTypeVoie = (doc.containsKey('idTypeVoie.keyword') && doc['idTypeVoie.keyword'].size() &gt; 0) ? doc['idTypeVoie.keyword'].value.length() : 0; return length_nomVoie + length_idTypeVoie;",
                    "lang": "painless"
                    },
                "order": "asc"
            }
        },
        {
            "_script": {
                "type": "string",
                "script": {
                    "source": "doc['idGaia'].value",
                    "lang": "painless"
                    },
